58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Syntactic email validation: a non-empty local part, a single '@', and a
65	     * domain with at least one dot-separated label ending in a letter-only TLD.
66	     */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
69	
70	    /** Dedicated audit logger for owner lifecycle side-effects. */
71	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    public OwnerRestControllerV1(ClinicService clinicService,
82	                                 OwnerMapper ownerMapper,
83	                                 PetMapper petMapper,
84	                                 VisitMapper visitMapper) {
85	        this.clinicService = clinicService;
86	        this.ownerMapper = ownerMapper;
87	        this.petMapper = petMapper;
88	        this.visitMapper = visitMapper;
89	    }
90	
91	    /**
92	     * Normalise a raw telephone number to E.164 form.
93	     *
94	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
95	     * code are kept when present; otherwise country code '+61' is assumed and a
96	     * single leading '0' is dropped from the national digits. The result must have
97	     * between 8 and 15 digits after the '+'.
98	     *
99	     * <p>When the caller supplies the country code explicitly (a leading '+'), the
100	     * national-number length is additionally validated against that country code:
101	     * '+61' requires 9 national digits and '+1' requires 10. A number whose national
102	     * length is wrong for its country is rejected.
103	     *
104	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
105	     */
106	    static String toE164(String raw) {
107	        if (raw == null) {
108	            return null;
109	        }
110	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
111	        String digits;
112	        boolean explicitCountryCode;
113	        if (cleaned.startsWith("+")) {
114	            digits = cleaned.substring(1);
115	            explicitCountryCode = true;
116	        } else {
117	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
118	            digits = "61" + national;
119	            explicitCountryCode = false;
120	        }
121	        if (!digits.matches("[0-9]{8,15}")) {
122	            return null;
123	        }
124	        if (explicitCountryCode && !hasValidNationalLength(digits)) {
125	            return null;
126	        }
127	        return "+" + digits;
128	    }
129	
130	    /**
131	     * Validate the national-number length of an E.164 number (its digits without the
132	     * leading '+') against the requirement for its country code: country code '+61'
133	     * (Australia) requires 9 national digits and '+1' (NANP) requires 10. Country codes
134	     * without a configured length requirement are accepted unchanged.
135	     */
136	    private static boolean hasValidNationalLength(String digits) {
137	        if (digits.startsWith("61")) {
138	            return digits.length() - "61".length() == 9;
139	        }
140	        if (digits.startsWith("1")) {
141	            return digits.length() - "1".length() == 10;
142	        }
143	        return true;
144	    }
145	
146	    /**
147	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
148	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
149	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
150	     * input normalises to the empty string.
151	     */
152	    private static String normaliseIdentity(String value) {
153	        if (value == null) {
154	            return "";
155	        }
156	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
157	    }
158	
159	    /**
160	     * Normalise a postal address into its canonical stored form: leading/trailing whitespace is
161	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
162	     * and common street-type abbreviations are expanded ({@code ST -> STREET}, {@code RD -> ROAD},
163	     * {@code AVE -> AVENUE}). A {@code null} input normalises to the empty string. This is the value
164	     * that is both stored and used for every address comparison.
165	     */
166	    static String normaliseAddress(String value) {
167	        if (value == null) {
168	            return "";
169	        }
170	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
171	        if (collapsed.isEmpty()) {
172	            return "";
173	        }
174	        String[] tokens = collapsed.split(" ");
175	        StringBuilder result = new StringBuilder();
176	        for (int i = 0; i < tokens.length; i++) {
177	            if (i > 0) {
178	                result.append(' ');
179	            }
180	            result.append(expandAddressAbbreviation(tokens[i]));
181	        }
182	        return result.toString();
183	    }
184	
185	    /**
186	     * Expand a single upper-cased address token if it is a known street-type abbreviation, ignoring a
187	     * trailing period (so both {@code ST} and {@code ST.} become {@code STREET}). Unknown tokens are
188	     * returned unchanged.
189	     */
190	    private static String expandAddressAbbreviation(String token) {
191	        String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
192	        return switch (core) {
193	            case "ST" -> "STREET";
194	            case "RD" -> "ROAD";
195	            case "AVE" -> "AVENUE";
196	            default -> token;
197	        };
198	    }
199	
200	    /**
201	     * Derive the stable, shared household identifier for owners sharing a household. It is a
202	     * deterministic UUID over the normalised last-name and address, so every owner in the same
203	     * household resolves to the same value regardless of the order in which they were created.
204	     */
205	    private static String householdId(String lastNameKey, String addressKey) {
206	        String seed = lastNameKey + "�" + addressKey;
207	        return UUID.nameUUIDFromBytes(seed.getBytes(StandardCharsets.UTF_8)).toString();
208	    }
209	
210	    /**
211	     * Build an owner's derived duplicate-detection identity key as
212	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Each {@code null}
213	     * component contributes the empty string, and the email is lower-cased so the comparison is
214	     * case-insensitive. Two owners are duplicates only when their whole identity keys are equal.
215	     */
216	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
217	        String telephone = normalizedTelephone == null ? "" : normalizedTelephone;
218	        String emailKey = email == null ? "" : email.toLowerCase();
219	        String household = householdId == null ? "" : householdId;
220	        return telephone + "|" + emailKey + "|" + household;
221	    }
222	
223	    /**
224	     * Build the customer code for a new owner as {@code '<CITY3>-<LAST3>-<NNNN>'}, where CITY3 is the
225	     * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
226	     * last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
227	     * owners already in that city at the time the owner was created.
228	     */
229	    private String nextCustomerCode(String city, String lastName) {
230	        String city3 = prefix3(city);
231	        String last3 = prefix3(lastName);
232	        String cityKey = normaliseIdentity(city);
233	        int sequence = (int) this.clinicService.findAllOwners().stream()
234	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
235	            .count() + 1;
236	        return String.format("%s-%s-%04d", city3, last3, sequence);
237	    }
238	
239	    /**
240	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
241	     * Sunday it is advanced to the following Monday; weekday dates are returned unchanged.
242	     */
243	    static LocalDate toBusinessDay(LocalDate date) {
244	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
245	            date = date.plusDays(1);
246	        }
247	        return date;
248	    }
249	
250	    /**
251	     * Count the owners already created on the business day that {@code registrationDate} rolls to,
252	     * using the same per-day accumulation path as the daily create-limit rule.
253	     */
254	    private long ownersCreatedOn(LocalDate registrationDate) {
255	        LocalDate day = toBusinessDay(registrationDate);
256	        return this.clinicService.findAllOwners().stream()
257	            .map(Owner::getRegistrationDate)
258	            .filter(existing -> existing != null)
259	            .map(OwnerRestControllerV1::toBusinessDay)
260	            .filter(day::equals)
261	            .count();
262	    }
263	
264	    /** Upper-cased first three characters of {@code value} (fewer if it is shorter); "" when null. */
265	    private static String prefix3(String value) {
266	        String letters = value == null ? "" : value;
267	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase();
268	    }
269	
270	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
271	    @Override
272	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
273	        Collection<Owner> owners;
274	        if (lastName != null) {
275	            owners = this.clinicService.findOwnerByLastName(lastName);
276	        } else {
277	            owners = this.clinicService.findAllOwners();
278	        }
279	        if (owners.isEmpty()) {
280	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
281	        }
282	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
283	    }
284	
285	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
286	    @Override
287	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
288	        Owner owner = this.clinicService.findOwnerById(ownerId);
289	        if (owner == null) {
290	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
291	        }
292	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
293	        ownerDto.setBulkSignupWarning(owner.getRegistrationDate() != null
294	            && ownersCreatedOn(owner.getRegistrationDate()) > 80);
295	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
296	    }
297	
298	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
299	    @Override
300	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
301	        String telephone = toE164(ownerFieldsDto.getTelephone());
302	        if (telephone == null) {
303	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
304	        }
305	        String email = ownerFieldsDto.getEmail();
306	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
307	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
308	        }
309	        String address = normaliseAddress(ownerFieldsDto.getAddress());
310	        if (address.isEmpty()) {
311	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
312	        }
313	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
314	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
315	        LocalDate registrationDate = toBusinessDay(effectiveDate);
316	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
317	            .map(Owner::getRegistrationDate)
318	            .filter(existing -> existing != null)
319	            .map(OwnerRestControllerV1::toBusinessDay)
320	            .filter(registrationDate::equals)
321	            .count();
322	        if (ownersCreatedThatDay >= 100) {
323	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
324	        }
325	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
326	        long ownersInCity = this.clinicService.findAllOwners().stream()
327	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
328	            .count();
329	        if (ownersInCity >= 50) {
330	            return new ResponseEntity<>(HttpStatus.CONFLICT);
331	        }
332	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
333	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
334	        String addressKey = address;
335	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
336	            .filter(existing ->
337	                normaliseIdentity(existing.getLastName()).equals(lastNameKey)
338	                    && normaliseAddress(existing.getAddress()).equals(addressKey))
339	            .toList();
340	        String householdId = (sharesHousehold && !householdMembers.isEmpty())
341	            ? householdId(lastNameKey, addressKey) : null;
342	        String identityKey = identityKey(telephone, email, householdId);
343	        boolean identityInUse = this.clinicService.findAllOwners().stream()
344	            .anyMatch(existing -> identityKey(toE164(existing.getTelephone()),
345	                existing.getEmail(), existing.getHouseholdId()).equals(identityKey));
346	        if (identityInUse) {
347	            return new ResponseEntity<>(HttpStatus.CONFLICT);
348	        }
349	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
350	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
351	            .filter(existing ->
352	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
353	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
354	            .count();
355	        HttpHeaders headers = new HttpHeaders();
356	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
357	        owner.setNamesakeCount(namesakeCount);
358	        owner.setAddress(address);
359	        owner.setTelephone(telephone);
360	        owner.setEmail(email == null ? null : email.toLowerCase());
361	        owner.setRegistrationDate(registrationDate);
362	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
363	        if (householdId != null) {
364	            owner.setHouseholdId(householdId);
365	            for (Owner member : householdMembers) {
366	                if (member.getHouseholdId() == null) {
367	                    member.setHouseholdId(householdId);
368	                    this.clinicService.saveOwner(member);
369	                }
370	            }
371	        }
372	        this.clinicService.saveOwner(owner);
373	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
374	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
375	            ownerMapper.formatMembershipLevel(owner));
376	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
377	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
378	        headers.setLocation(UriComponentsBuilder.newInstance()
379	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
380	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
381	    }
382	
383	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
384	    @Override
385	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
386	        String telephone = toE164(ownerFieldsDto.getTelephone());
387	        if (telephone == null) {
388	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
389	        }
390	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
391	        if (currentOwner == null) {
392	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
393	        }
394	        String email = ownerFieldsDto.getEmail();
395	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
396	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
397	        }
398	        currentOwner.setAddress(ownerFieldsDto.getAddress());
399	        currentOwner.setCity(ownerFieldsDto.getCity());
400	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
401	        currentOwner.setLastName(ownerFieldsDto.getLastName());
402	        currentOwner.setTelephone(telephone);
403	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
404	        this.clinicService.saveOwner(currentOwner);
405	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
406	    }
407	
408	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
409	    @Transactional
410	    @Override
411	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
412	        Owner owner = this.clinicService.findOwnerById(ownerId);
413	        if (owner == null) {
414	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
415	        }
416	        this.clinicService.deleteOwner(owner);
417	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
418	    }
419	
420	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
421	    @Override
422	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
423	        Owner owner = this.clinicService.findOwnerById(ownerId);
424	        if (owner == null) {
425	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
426	        }
427	        HttpHeaders headers = new HttpHeaders();
428	        Pet pet = petMapper.toPet(petFieldsDto);
429	        owner.setId(ownerId);
430	        pet.setOwner(owner);
431	        pet.getType().setName(null);
432	        this.clinicService.savePet(pet);
433	        PetDto petDto = petMapper.toPetDto(pet);
434	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
435	            .buildAndExpand(pet.getId()).toUri());
436	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
437	    }
438	
439	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
440	    @Override
441	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
442	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
443	        if (currentOwner != null) {
444	            Pet currentPet = this.clinicService.findPetById(petId);
445	            if (currentPet != null) {
446	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
447	                currentPet.setName(petFieldsDto.getName());
448	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
449	                this.clinicService.savePet(currentPet);
450	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
451	            }
452	        }
453	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
454	    }
455	
456	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
457	    @Override
458	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
459	        HttpHeaders headers = new HttpHeaders();
460	        Visit visit = visitMapper.toVisit(visitFieldsDto);
461	        Pet pet = new Pet();
462	        pet.setId(petId);
463	        visit.setPet(pet);
464	        this.clinicService.saveVisit(visit);
465	        VisitDto visitDto = visitMapper.toVisitDto(visit);
466	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
467	            .buildAndExpand(visit.getId()).toUri());
468	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
469	    }
470	
471	
472	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
473	    @Override
474	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
475	        Owner owner = this.clinicService.findOwnerById(ownerId);
476	        if (owner != null) {
477	            Pet pet = owner.getPet(petId);
478	            if (pet != null) {
479	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
480	            }
481	        }
482	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
483	    }
484	}
